-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.frame_on_jetty_below(p_world uuid, p_building integer, p_level integer, p_x integer, p_y integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  select p_level >= 2
     and exists (select 1 from floor_tile f where f.world_id = p_world and f.level = p_level - 1 and f.x = p_x and f.y = p_y
                   and f.building = p_building and bill_done(f.needed) and f.kind = 'floor')
     and exists (select 1 from frame_storey(p_world, p_building, p_level - 1) a where a.x = p_x and a.y = p_y)
$function$
